  const importer=document.createElement('section');importer.id='rosterImport';importer.className='admin-section';importer.innerHTML=`<h2>名冊匯入</h2><p class="muted">CSV／XLSX，每次最多200筆、512KB。先預覽，全部正確後才寫入；空白更新欄位保留原值。</p><div class="toolbar"><button type="button" id="templateCsv" class="secondary">下載 CSV 範本</button><button type="button" id="templateXlsx" class="secondary">下載 Excel 範本</button></div><label for="rosterFile">選擇虛構員工名冊</label><input type="file" id="rosterFile" accept=".csv,.xlsx"><div class="toolbar"><button type="button" id="previewRosterImport">預覽與檢查</button><button type="button" id="commitRosterImport" disabled>確認匯入測試名冊</button><button type="button" id="cancelRosterImport" class="secondary">取消匯入</button></div><p id="importMessage" class="status-message" role="status"></p><div id="importSummary" class="import-summary"></div><div class="table-wrap" id="importTable" hidden><table><thead><tr><th>行號</th><th>員工編號／姓名</th><th>部門</th><th>表單／期別</th><th>處理方式</th><th>檢查結果</th></tr></thead><tbody id="importRows"></tbody></table></div>`;
