  function renderRoster(){
   const search=$('rosterSearch').value.trim(),department=$('rosterDepartmentFilter').value,type=$('rosterTypeFilter').value,status=$('rosterStatusFilter').value;
   const visible=employees.filter(e=>(!search||[e.id,e.name,e.department,e.title,e.site].join(' ').includes(search))&&(!department||e.department===department)&&(!type||e.applicablePeriods.some(p=>e.assignments?.[p]===type))&&(!status||e.employmentStatus===status));
   filteredRoster=visible;const size=Number($('rosterPageSize').value),pages=Math.max(1,Math.ceil(visible.length/size));currentPage=Math.max(1,Math.min(currentPage,pages));$('rosterPage').textContent=currentPage+' / '+pages+' ('+visible.length+')';$('rosterPrev').disabled=currentPage===1;$('rosterNext').disabled=currentPage===pages;window.HRGoogleCache.setItem('stage8-roster-'+context.id,JSON.stringify({currentPage,size,filters:Object.fromEntries(['rosterSearch','rosterDepartmentFilter','rosterTypeFilter','rosterStatusFilter'].map(id=>[id,$(id).value]))}));
   const rows=visible.slice((currentPage-1)*size,currentPage*size).map(e=>{const tr=document.createElement('tr'),check=document.createElement('input');check.type='checkbox';check.checked=selected.has(e.id);check.setAttribute('aria-label','選取 '+e.name);check.dataset.rosterSelect=e.id;check.onchange=()=>{selectionRange='手動勾選';check.checked?selected.add(e.id):selected.delete(e.id);selectionCount()};cell(tr,'').append(check);cell(tr,e.id);cell(tr,e.name+'\n'+e.department);cell(tr,e.title);cell(tr,e.applicablePeriods.map(p=>p+'：'+typeName(e.assignments?.[p])).join('\n'));cell(tr,e.hireDate||'待確認');cell(tr,({active:'在職',inactive:'停用',left:'離職'})[e.employmentStatus]);cell(tr,e.updatedAt?new Date(e.updatedAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'—');const buttons=cell(tr,'');buttons.className='compact-actions';for(const [label,action]of [['編輯','edit'],['分配','assign'],[e.active?'停用':'啟用','active']]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=label;b.dataset.rosterAction=action;b.dataset.employee=e.id;b.onclick=async()=>{if(action==='edit')editEmployee(e);else if(action==='assign'){assignmentController.select([e.id]);assignment.scrollIntoView({block:'start'})}else{if(!await window.HRUI.confirm((e.active?'停用後將禁止此員工登入，既有考績仍保留。':'將重新啟用此測試員工。')+'確定繼續？'))return;try{await request('/api/roster/save',{employeeId:e.id,status:e.active?'inactive':'active'});await reload();message('rosterMessage','狀態已更新。')}catch(error){message('rosterMessage',error.message,true)}}};buttons.append(b)}return tr});
   $('rosterRows').replaceChildren(...rows);if(!rows.length){const tr=document.createElement('tr'),td=cell(tr,'沒有符合條件的員工');td.colSpan=9;$('rosterRows').append(tr)}selectionCount();
  }
  function selectionCount(){$('rosterSelected').textContent='已選 '+selected.size+' 人'+(selected.size?' · '+selectionRange:'')}
  function resetEditor(){$('rosterEditor').reset();$('rosterId').readOnly=false;$('rosterType').disabled=false;$('rosterType').required=true;$('rosterType').parentElement.hidden=false;$('rosterEditorTitle').textContent='新增員工'}
