  $('newEmployee').onclick=async()=>{if(window.HRManagementDrafts?.dirty.has('rosterEditor')&&!await window.HRUI.confirm('確定放棄未儲存的編輯？'))return;window.HRManagementDrafts?.clear('rosterEditor');resetEditor();$('rosterEditor').hidden=false;$('rosterEditor').scrollIntoView({block:'start'});$('rosterId').focus();document.dispatchEvent(new Event('roster-editor-state'))};$('cancelRosterEdit').onclick=()=>{window.HRManagementDrafts?.clear('rosterEditor');resetEditor();$('rosterEditor').hidden=true;document.dispatchEvent(new Event('roster-editor-state'));message('rosterMessage','已取消編輯，既有資料未變更。')};$('clearRosterSelection').onclick=()=>{selected.clear();renderRoster()};$('exportRoster').onclick=()=>download('/api/roster/export').catch(e=>message('rosterMessage',e.message,true));
  for(const id of ['rosterSearch','rosterDepartmentFilter','rosterTypeFilter','rosterStatusFilter'])$(id).addEventListener(id==='rosterSearch'?'input':'change',e=>{if(!e.isComposing){currentPage=1;renderRoster()}});$('rosterSearch').addEventListener('compositionend',renderRoster);
  $('rosterEditor').onsubmit=async event=>{event.preventDefault();const body={expectedRevision:$('rosterId').readOnly?editingRevision:undefined,employeeId:$('rosterId').value.trim(),hireDate:$('rosterHireDate').value,name:$('rosterName').value.trim(),department:$('rosterDepartment').value.trim(),title:$('rosterTitle').value.trim(),site:$('rosterSite').value.trim(),formRole:$('rosterType').disabled?'':$('rosterType').value,status:$('rosterStatus').value,periods:[...document.querySelectorAll('[name=applicablePeriod]:checked')].map(b=>b.value).join('|'),mockCode:$('rosterMockCode').value};if(!body.periods){message('rosterMessage','請選擇至少一個適用期別。',true);return}$('saveRosterEmployee').disabled=true;try{try{await request('/api/roster/save',body)}catch(error){if(error.status!==409||!error.report)throw error;if(!await window.HRUI.confirm('確認調整到職日？可能影響各期填寫資格，已送出內容、資格快照及歷史設定仍保留。'))return;await request('/api/roster/save',{...body,impactConfirmed:true,version:error.report.version})}window.HRManagementDrafts?.clear('rosterEditor');await reload();editEmployee(employees.find(e=>e.id===body.employeeId));message('rosterMessage','員工已儲存；既有考績未覆蓋。')}catch(error){message('rosterMessage',error.report?.rows.flatMap(r=>r.errors).join('；')||error.message,true)}finally{$('saveRosterEmployee').disabled=false}};
  for(const [id,format]of [['templateCsv','csv'],['templateXlsx','xlsx']])$(id).onclick=()=>download('/api/roster/template?format='+format).catch(e=>message('importMessage',e.message,true));
  function showPreview(report){preview=report;$('importRows').replaceChildren();$('importSummary').replaceChildren();const labels={total:'總筆數',create:'新增',update:'更新',unchanged:'不變',duplicate:'重複',errors:'錯誤'};for(const [k,label]of Object.entries(labels)){const tag=document.createElement('span');tag.textContent=label+' '+(report.summary?.[k]||0);$('importSummary').append(tag)}for(const r of report.rows||[]){const tr=document.createElement('tr');cell(tr,r.line);cell(tr,r.employeeId+'\n'+r.name);cell(tr,r.data?.department);cell(tr,(r.data?.applicablePeriods||[]).map(p=>p+' '+typeName(r.data.assignments[p])).join('\n'));cell(tr,({create:'新增',update:'更新',unchanged:'不變',duplicate:'重複',error:'錯誤'})[r.action]);const td=cell(tr,r.errors.length?r.errors.join('；'):'檢查通過');if(r.errors.length)td.className='error-cell';$('importRows').append(tr)}$('importTable').hidden=!report.rows?.length;$('commitRosterImport').disabled=!report.valid;message('importMessage',report.errors?.length?report.errors.join('；'):report.valid?'預覽通過，尚未寫入。請核對後按「確認匯入測試名冊」。':'請依行號修正錯誤；本次未寫入任何資料。',!report.valid)}
  async function cancelImport(){preview=null;$('commitRosterImport').disabled=true;$('importTable').hidden=true;$('importRows').replaceChildren();$('importSummary').replaceChildren();await request('/api/roster/cancel',{})}
  let cancelPending=Promise.resolve();
  $('cancelRosterImport').onclick=()=>cancelImport().then(()=>message('importMessage','已取消，名冊未變更。')).catch(e=>message('importMessage',e.message,true));$('rosterFile').onchange=()=>{cancelPending=cancelImport().catch(()=>{})};
  $('previewRosterImport').onclick=async()=>{const file=$('rosterFile').files[0];if(!file){message('importMessage','請先選擇 CSV 或 XLSX 檔案。',true);return}if(file.size>524288||!(/\.(csv|xlsx)$/i.test(file.name))){message('importMessage','請選擇512KB內的CSV或XLSX。',true);return}$('previewRosterImport').disabled=true;$('rosterFile').disabled=true;$('cancelRosterImport').disabled=true;$('commitRosterImport').disabled=true;try{await cancelPending;const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const report=await request('/api/roster/preview',{format:file.name.toLowerCase().endsWith('.xlsx')?'xlsx':'csv',content:btoa(binary)});showPreview(report)}catch(error){message('importMessage',error.message,true)}finally{$('previewRosterImport').disabled=false;$('rosterFile').disabled=false;$('cancelRosterImport').disabled=false}};
